import{_ as t,a0 as l,w as o,s as c,ao as d,I as p,x as n,a1 as e,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const N=JSON.parse('{"title":"awk 系列：如何使用 awk 的特殊模式 BEGIN 和 END | LCTT x X-CMD","titleTemplate":false,"description":"awk 系列：如何使用 awk 的特殊模式 BEGIN 和 END | LCTT (awk) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"awk 系列：如何使用 awk 的特殊模式 BEGIN 和 END | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"awk 系列：如何使用 awk 的特殊模式 BEGIN 和 END | LCTT (awk) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"awk/Part 9 - Learn How to Use Awk Special Patterns begin and end","title":"awk 系列：如何使用 awk 的特殊模式 BEGIN 和 END","tag":"awk","desc":""},"relativePath":"awk/Part 9 - Learn How to Use Awk Special Patterns begin and end.md","filePath":"[post].md"}'),r={name:"awk/Part 9 - Learn How to Use Awk Special Patterns begin and end.md"};function k(h,s,g,m,u,w){const a=l("Link");return o(),c("div",null,[s[13]||(s[13]=d(`<h1 id="awk-系列-如何使用-awk-的特殊模式-begin-和-end" tabindex="-1">awk 系列：如何使用 awk 的特殊模式 BEGIN 和 END <a class="header-anchor" href="#awk-系列-如何使用-awk-的特殊模式-begin-和-end" aria-label="Permalink to “awk 系列：如何使用 awk 的特殊模式 BEGIN 和 END”">​</a></h1><p>在 awk 系列的第八節，我們介紹了一些強大的 awk 命令功能，它們是變量、數字表達式和賦值運算符。</p><p>本節我們將學習更多的 awk 功能，即 awk 的特殊模式：<code>BEGIN</code> 和 <code>END</code>。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2016/07/Learn-Awk-Patterns-BEGIN-and-END.png" alt=""></p><blockquote><p>學習 awk 的模式 BEGIN 和 END</p></blockquote><p>隨着我們逐漸展開，並探索出更多構建複雜 awk 操作的方法，將會證明 awk 的這些特殊功能的是多麼強大。</p><p>開始前，先讓我們回顧一下 awk 系列的介紹，記得當我們開始這個系列時，我就指出 awk 指令的通用語法是這樣的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># awk &#39;script&#39; filenames</span></span></code></pre></div><p>在上述語法中，awk 腳本擁有這樣的形式：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/pattern/ { actions }</span></span></code></pre></div><p>你通常會發現腳本中的模式（<code>/pattern/</code>）是一個正則表達式，不過你也可以將模式使用特殊模式 <code>BEGIN</code> 和 <code>END</code>。因此，我們也能按照下面的形式編寫一條 awk 命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>awk &#39;</span></span>
<span class="line"><span>BEGIN { actions } </span></span>
<span class="line"><span>/pattern/ { actions }</span></span>
<span class="line"><span>/pattern/ { actions }</span></span>
<span class="line"><span>……….</span></span>
<span class="line"><span>END { actions } </span></span>
<span class="line"><span>&#39; filenames</span></span></code></pre></div><p>假如你在 awk 腳本中使用了特殊模式：<code>BEGIN</code> 和 <code>END</code>，以下則是它們對應的含義：</p><ul><li><code>BEGIN</code> 模式：是指 awk 將在讀取任何輸入行之前立即執行 <code>BEGIN</code> 中指定的動作。</li><li><code>END</code> 模式：是指 awk 將在它正式退出前執行 <code>END</code> 中指定的動作。</li></ul><p>含有這些特殊模式的 awk 命令腳本的執行流程如下：</p><ol><li>當在腳本中使用了 <code>BEGIN</code> 模式，則 <code>BEGIN</code> 中所有的動作都會在讀取任何輸入行之前執行。</li><li>然後，讀入一個輸入行並解析成不同的段。</li><li>接下來，每一條指定的非特殊模式都會和輸入行進行比較匹配，當匹配成功後，就會執行模式對應的動作。對所有你指定的模式重複此執行該步驟。</li><li>再接下來，對於所有輸入行重複執行步驟 2 和 步驟 3。</li><li>當讀取並處理完所有輸入行後，假如你指定了 <code>END</code> 模式，那麼將會執行相應的動作。</li></ol><p>當你使用特殊模式時，想要在 awk 操作中獲得最好的結果，你應當記住上面的執行順序。</p><p>為了便於理解，讓我們使用第八節的例子進行演示，那個例子是關於 Tecmint 擁有的域名列表，並保存在一個叫做 domains.txt 的文件中。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>news.tecmint.com</span></span>
<span class="line"><span>tecmint.com</span></span>
<span class="line"><span>linuxsay.com</span></span>
<span class="line"><span>windows.tecmint.com</span></span>
<span class="line"><span>tecmint.com</span></span>
<span class="line"><span>news.tecmint.com</span></span>
<span class="line"><span>tecmint.com</span></span>
<span class="line"><span>linuxsay.com</span></span>
<span class="line"><span>tecmint.com</span></span>
<span class="line"><span>news.tecmint.com</span></span>
<span class="line"><span>tecmint.com</span></span>
<span class="line"><span>linuxsay.com</span></span>
<span class="line"><span>windows.tecmint.com</span></span>
<span class="line"><span>tecmint.com</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat ~/domains.txt</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/07/View-Contents-of-File.png" alt=""></p><p><em>查看文件內容</em></p><p>在這個例子中，我們希望統計出 domains.txt 文件中域名 <code>tecmint.com</code> 出現的次數。所以，我們編寫了一個簡單的 shell 腳本幫助我們完成任務，它使用了變量、數學表達式和賦值運算符的思想，腳本內容如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span>for file in $@; do</span></span>
<span class="line"><span>if [ -f $file ] ; then</span></span>
<span class="line"><span>### 輸出文件名</span></span>
<span class="line"><span>echo &quot;File is: $file&quot;</span></span>
<span class="line"><span>### 輸出一個遞增的數字記錄包含 tecmint.com 的行數</span></span>
<span class="line"><span>awk &#39;/^tecmint.com/ { counter+=1 ; printf &quot;%s\\n&quot;, counter ; }&#39; $file</span></span>
<span class="line"><span>else</span></span>
<span class="line"><span>### 若輸入不是文件，則輸出錯誤信息</span></span>
<span class="line"><span>echo &quot;$file 不是一個文件，請指定一個文件。&quot; &gt;&amp;2 &amp;&amp; exit 1</span></span>
<span class="line"><span>fi</span></span>
<span class="line"><span>done</span></span>
<span class="line"><span>### 成功執行後使用退出代碼 0 終止腳本</span></span>
<span class="line"><span>exit 0</span></span></code></pre></div><p>現在讓我們像下面這樣在上述腳本的 awk 命令中應用這兩個特殊模式：<code>BEGIN</code> 和 <code>END</code>：</p><p>我們應當把腳本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>awk &#39;/^tecmint.com/ { counter+=1 ; printf &quot;%s\\n&quot;, counter ; }&#39; $file</span></span></code></pre></div><p>改成：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>awk &#39; BEGIN {  print &quot;文件中出現 tecmint.com 的次數是：&quot; ; }</span></span>
<span class="line"><span>/^tecmint.com/ {  counter+=1  ;  }</span></span>
<span class="line"><span>END {  printf &quot;%s\\n&quot;,  counter  ; } </span></span>
<span class="line"><span>&#39;  $file</span></span></code></pre></div><p>在修改了 awk 命令之後，現在完整的 shell 腳本就像下面這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span>for file in $@; do</span></span>
<span class="line"><span>if [ -f $file ] ; then</span></span>
<span class="line"><span>### 輸出文件名</span></span>
<span class="line"><span>echo &quot;File is: $file&quot;</span></span>
<span class="line"><span>### 輸出文件中 tecmint.com 出現的總次數</span></span>
<span class="line"><span>awk &#39; BEGIN {  print &quot;文件中出現 tecmint.com 的次數是：&quot; ; }</span></span>
<span class="line"><span>/^tecmint.com/ {  counter+=1  ;  }</span></span>
<span class="line"><span>END {  printf &quot;%s\\n&quot;,  counter  ; } </span></span>
<span class="line"><span>&#39;  $file</span></span>
<span class="line"><span>else</span></span>
<span class="line"><span>### 若輸入不是文件，則輸出錯誤信息</span></span>
<span class="line"><span>echo &quot;$file 不是一個文件，請指定一個文件。&quot; &gt;&amp;2 &amp;&amp; exit 1</span></span>
<span class="line"><span>fi</span></span>
<span class="line"><span>done</span></span>
<span class="line"><span>### 成功執行後使用退出代碼 0 終止腳本</span></span>
<span class="line"><span>exit 0</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/07/Awk-BEGIN-and-END-Patterns.png" alt=""></p><p><em>awk 模式 BEGIN 和 END</em></p><p>當我們運行上面的腳本時，它會首先輸出 domains.txt 文件的位置，然後執行 awk 命令腳本，該命令腳本中的特殊模式 <code>BEGIN</code> 將會在從文件讀取任何行之前幫助我們輸出這樣的消息“<code>文件中出現 tecmint.com 的次數是：</code>”。</p><p>接下來，我們的模式 <code>/^tecmint.com/</code> 會在每個輸入行中進行比較，對應的動作 <code>{ counter+=1 ; }</code> 會在每個匹配成功的行上執行，它會統計出 <code>tecmint.com</code> 在文件中出現的次數。</p><p>最終，<code>END</code> 模式將會輸出域名 <code>tecmint.com</code> 在文件中出現的總次數。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ./script.sh ~/domains.txt</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/07/Script-to-Count-Number-of-Times-String-Appears.png" alt=""></p><p><em>用於統計字符串出現次數的腳本</em></p><p>最後總結一下，我們在本節中演示了更多的 awk 功能，並學習了特殊模式 <code>BEGIN</code> 和 <code>END</code> 的概念。</p><p>正如我之前所言，這些 awk 功能將會幫助我們構建出更復雜的文本過濾操作。第十節將會給出更多的 awk 功能，我們將會學習 awk 內置變量的思想，所以，請繼續保持關注。</p><hr>`,42)),p("p",null,[s[1]||(s[1]=n("via: ",-1)),e(a,{href:"http://www.tecmint.com/learn-use-awk-special-patterns-begin-and-end/"},{default:i(()=>[...s[0]||(s[0]=[n("http://www.tecmint.com/learn-use-awk-special-patterns-begin-and-end/",-1)])]),_:1})]),p("p",null,[s[5]||(s[5]=n("作者：",-1)),e(a,{href:"http://www.tecmint.com/author/aaronkili/"},{default:i(()=>[...s[2]||(s[2]=[n("Aaron Kili",-1)])]),_:1}),s[6]||(s[6]=n(" 譯者：",-1)),e(a,{href:"https://github.com/chrisleegit"},{default:i(()=>[...s[3]||(s[3]=[n("ChrisLeeGit",-1)])]),_:1}),s[7]||(s[7]=n(" 校對：",-1)),e(a,{href:"https://github.com/wxy"},{default:i(()=>[...s[4]||(s[4]=[n("wxy",-1)])]),_:1})]),p("p",null,[s[10]||(s[10]=n("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[8]||(s[8]=[n("LCTT",-1)])]),_:1}),s[11]||(s[11]=n(" 原創編譯，",-1)),e(a,{href:"https://linux.cn/"},{default:i(()=>[...s[9]||(s[9]=[n("Linux中國",-1)])]),_:1}),s[12]||(s[12]=n(" 榮譽推出",-1))])])}const E=t(r,[["render",k]]);export{N as __pageData,E as default};
